var makeMiddleware = require('./lib/make-middleware')

var diskStorage = require('./storage/disk')
var memoryStorage = require('./storage/memory')
var MulterError = require('./lib/multer-error')
var validateLimits = require('./lib/validate-limits')

/**
 * A file parsed from a multipart request.
 *
 * @typedef {Object} File
 * @property {string} fieldname Name of the form field
 * @property {string} originalname Name of the file on the client (client-supplied, treat as untrusted)
 * @property {string} encoding Transfer encoding of the file
 * @property {string} mimetype MIME type of the file
 * @property {number} [size] Size of the file in bytes; set once the file has been stored
 * @property {ReadableStream} [stream] The file data; only present while a storage engine's `_handleFile` runs
 * @property {string} [destination] Folder the file was saved to (`DiskStorage`)
 * @property {string} [filename] Name of the file within `destination` (`DiskStorage`)
 * @property {string} [path] Full path of the saved file (`DiskStorage`)
 * @property {Buffer} [buffer] Contents of the file (`MemoryStorage`)
 */

/**
 * Size limits, passed to busboy. All are optional.
 *
 * @typedef {Object} Limits
 * @property {number} [fieldNameSize=100] Max field name size in bytes
 * @property {number} [fieldSize=1048576] Max field value size in bytes
 * @property {number} [fields=Infinity] Max number of non-file fields
 * @property {number} [fileSize=Infinity] Max file size in bytes (integer or `Infinity`)
 * @property {number} [files=Infinity] Max number of file fields
 * @property {number} [parts=Infinity] Max number of parts (fields + files)
 * @property {number} [headerPairs=2000] Max number of header key/value pairs to parse
 * @property {number} [fieldNestingDepth=Infinity] Max nesting depth of field names (`a[b][c]` has 2 levels)
 * @property {number} [fieldArrayIndexLimit=Infinity] Max numeric array index accepted in field names
 */

/**
 * Decides whether a file is accepted. Call `cb(null, true)` to accept the
 * file, `cb(null, false)` to skip it silently, or `cb(err)` to abort.
 *
 * @callback FileFilter
 * @param {Object} req The request
 * @param {File} file The file being uploaded; `size`, `stream`, `path` and `buffer` are not set yet
 * @param {function(?Error, boolean=): void} cb
 */

/**
 * Storage engine. See StorageEngine.md for the full contract.
 *
 * @typedef {Object} StorageEngine
 * @property {function(Object, File, function(?Error, Object=): void): void} _handleFile
 *   Consumes `file.stream` and calls back with the properties to merge into the file object
 * @property {function(Object, File, function(?Error): void): void} _removeFile
 *   Removes a stored file when the request fails
 */

/**
 * @typedef {Object} Options
 * @property {string} [dest] Folder to store files in (uses `DiskStorage`)
 * @property {StorageEngine} [storage] Storage engine; defaults to `MemoryStorage` when neither `dest` nor `storage` is set
 * @property {FileFilter} [fileFilter] Controls which files are accepted
 * @property {Limits|function(Object): Limits} [limits] Size limits, or a function of the request returning them
 * @property {boolean} [preservePath=false] Keep the full client-supplied path in `file.originalname`
 * @property {string} [defParamCharset='latin1'] Charset for part header parameters (e.g. filename) without an explicit one
 * @property {string} [defCharset='utf8'] Charset for text field values that do not declare one
 * @property {number} [highWaterMark] `highWaterMark` of the multipart parser stream; busboy's default
 * @property {number} [fileHwm] `highWaterMark` of each file stream (`file.stream`); busboy's default
 * @property {function(Object, Object): void} [streamHandler] Feeds the request body to busboy; defaults to `req.pipe(busboy)`
 */

function allowAll (req, file, cb) {
  cb(null, true)
}

/**
 * @constructor
 * @private
 * @param {Options} options
 */
function Multer (options) {
  if (options.storage) {
    this.storage = options.storage
  } else if (options.dest) {
    this.storage = diskStorage({ destination: options.dest })
  } else {
    this.storage = memoryStorage()
  }

  if (options.limits && typeof options.limits !== 'function') validateLimits(options.limits)

  this.limits = options.limits
  this.preservePath = options.preservePath
  this.defParamCharset = options.defParamCharset || 'latin1'
  this.defCharset = options.defCharset
  this.highWaterMark = options.highWaterMark
  this.fileHwm = options.fileHwm
  this.fileFilter = options.fileFilter || allowAll

  if (options.streamHandler !== undefined && typeof options.streamHandler !== 'function') {
    throw new TypeError('Expected streamHandler to be a function')
  }

  this.streamHandler = options.streamHandler
}

Multer.prototype._makeMiddleware = function (fields, fileStrategy) {
  function setup () {
    var fileFilter = this.fileFilter
    var filesLeft = Object.create(null)

    fields.forEach(function (field) {
      if (typeof field.maxCount === 'number') {
        filesLeft[field.name] = field.maxCount
      } else {
        filesLeft[field.name] = Infinity
      }
    })

    function wrappedFileFilter (req, file, cb) {
      if ((filesLeft[file.fieldname] || 0) <= 0) {
        return cb(new MulterError('LIMIT_UNEXPECTED_FILE', file.fieldname, file.originalname))
      }

      // Reserve the slot synchronously before yielding to the async fileFilter,
      // so files emitted together in one busboy write cannot all read the
      // pre-decrement count and slip past maxCount. Release it on reject/error
      // (a skipped file must not consume a slot, #1419), and only once so a
      // filter that calls back repeatedly cannot leak slots.
      filesLeft[file.fieldname] -= 1

      var settled = false
      fileFilter(req, file, function (err, includeFile) {
        if (!settled) {
          settled = true
          if (err || !includeFile) filesLeft[file.fieldname] += 1
        }

        cb(err, includeFile)
      })
    }

    return {
      limits: this.limits,
      preservePath: this.preservePath,
      defParamCharset: this.defParamCharset,
      defCharset: this.defCharset,
      highWaterMark: this.highWaterMark,
      fileHwm: this.fileHwm,
      streamHandler: this.streamHandler,
      storage: this.storage,
      fileFilter: wrappedFileFilter,
      fileStrategy: fileStrategy
    }
  }

  return makeMiddleware(setup.bind(this))
}

/**
 * Accept a single file for the field `name`. The file is stored in `req.file`.
 *
 * @param {string} name
 * @returns {function(Object, Object, function(?Error): void): void} Express middleware
 */
Multer.prototype.single = function (name) {
  return this._makeMiddleware([{ name: name, maxCount: 1 }], 'VALUE')
}

/**
 * Accept an array of files for the field `name`, stored in `req.files`.
 * Files skipped by `fileFilter` do not count towards `maxCount`.
 *
 * @param {string} name
 * @param {number} [maxCount] Error with `LIMIT_UNEXPECTED_FILE` if more files are accepted
 * @returns {function(Object, Object, function(?Error): void): void} Express middleware
 */
Multer.prototype.array = function (name, maxCount) {
  return this._makeMiddleware([{ name: name, maxCount: maxCount }], 'ARRAY')
}

/**
 * Accept a mix of files. `req.files` is an object keyed by field name, each
 * value an array of files.
 *
 * @param {Array<{name: string, maxCount?: number}>} fields
 * @returns {function(Object, Object, function(?Error): void): void} Express middleware
 */
Multer.prototype.fields = function (fields) {
  return this._makeMiddleware(fields, 'OBJECT')
}

/**
 * Accept only text fields. Any file results in a `LIMIT_UNEXPECTED_FILE` error.
 *
 * @returns {function(Object, Object, function(?Error): void): void} Express middleware
 */
Multer.prototype.none = function () {
  return this._makeMiddleware([], 'NONE')
}

/**
 * Accept all files, stored as an array in `req.files`. Only use this on routes
 * that handle every uploaded file.
 *
 * @returns {function(Object, Object, function(?Error): void): void} Express middleware
 */
Multer.prototype.any = function () {
  function setup () {
    return {
      limits: this.limits,
      preservePath: this.preservePath,
      defParamCharset: this.defParamCharset,
      defCharset: this.defCharset,
      highWaterMark: this.highWaterMark,
      fileHwm: this.fileHwm,
      streamHandler: this.streamHandler,
      storage: this.storage,
      fileFilter: this.fileFilter,
      fileStrategy: 'ARRAY'
    }
  }

  return makeMiddleware(setup.bind(this))
}

/**
 * Create a multer instance. Text fields are parsed into `req.body`; files go to
 * `req.file` or `req.files` depending on the method used.
 *
 * @param {Options} [options]
 * @returns {Multer}
 * @throws {TypeError} If `options` is not an object
 */
function multer (options) {
  if (options === undefined) {
    return new Multer({})
  }

  if (typeof options === 'object' && options !== null) {
    return new Multer(options)
  }

  throw new TypeError('Expected object for argument options')
}

module.exports = multer
module.exports.diskStorage = diskStorage
module.exports.memoryStorage = memoryStorage
module.exports.MulterError = MulterError

var is = require('type-is')
var AsyncResource = require('async_hooks').AsyncResource
var Busboy = require('busboy')
var appendField = require('append-field')

var Counter = require('./counter')
var MulterError = require('./multer-error')
var FileAppender = require('./file-appender')
var removeUploadedFiles = require('./remove-uploaded-files')
var validateLimits = require('./validate-limits')

// append-field turns a bracket group whose contents are all digits into an
// array index, so `a[3]` produces an array of length 4. The index itself is
// unbounded, which means a single field name can materialize a sparse array
// with a very large length. That costs append-field almost nothing, but it is
// the application that pays when it later iterates or serializes req.body, and
// until now there was no limit to opt into.
function exceedsArrayIndexLimit (fieldname, limit) {
  // Only field names append-field parses as a bracket path build an array;
  // names it stores as a literal key (e.g. a[6]suffix, [6]) never do, so they
  // must not be rejected by the index limit.
  if (!/^[^[]+(?:\[[^\]]+\])*(?:\[\])?$/.test(fieldname)) return false

  var pattern = /\[(\d+)\]/g
  var match

  while ((match = pattern.exec(fieldname)) !== null) {
    if (Number(match[1]) > limit) return true
  }

  return false
}

function drainStream (stream) {
  stream.on('readable', () => {
    while (stream.read() !== null) {}
  })
}

// The WHATWG HTML spec requires user agents to escape the bytes 0x0A (LF),
// 0x0D (CR) and 0x22 (") as %0A, %0D and %22 when serialising field names and
// filenames in a multipart/form-data body. Busboy leaves them escaped, so we
// reverse exactly those three sequences here to recover the original name.
// Only these are decoded on purpose: a bare `%` is never escaped by the spec,
// so a full decodeURIComponent would corrupt legitimate names like `50%.pdf`.
// https://html.spec.whatwg.org/multipage/form-control-infrastructure.html#multipart-form-data
function decodeFormDataName (str) {
  return str.replace(/%0A|%0D|%22/gi, function (match) {
    switch (match.toUpperCase()) {
      case '%0A': return '\n'
      case '%0D': return '\r'
      default: return '"'
    }
  })
}

// By default the request is piped into busboy. Environments that have already
// consumed the request body (e.g. Google Cloud Functions, which exposes it as
// `req.rawBody`) can provide a `streamHandler` that feeds busboy instead.
function defaultStreamHandler (req, busboy) {
  req.pipe(busboy)
}

function makeMiddleware (setup) {
  return function multerMiddleware (req, res, next) {
    // Preserve the caller's async context (AsyncLocalStorage, CLS) across the
    // busboy stream events that eventually call next(). runInAsyncScope exists
    // since Node 9 and passes arguments through on every version, unlike the
    // static AsyncResource.bind, which drops them on Node 14.
    var resource = new AsyncResource('multer')
    var originalNext = next
    next = function (err) {
      resource.runInAsyncScope(originalNext, null, err)
    }

    if (!is(req, ['multipart'])) return next()

    var options = setup()

    var limits = options.limits

    // limits can be a function of the request, evaluated once per request
    if (typeof limits === 'function') {
      try {
        limits = limits(req)
        if (limits) validateLimits(limits)
      } catch (err) {
        return next(err)
      }
    }

    var busboyLimits = limits

    // busboy fires 'limit' when the file size reaches limits.fileSize and
    // 'partsLimit' when the part count reaches limits.parts. Multer treats
    // both as "max allowed", so pass one more to busboy and let it fire only
    // once the limit is actually exceeded.
    if (limits && (Object.prototype.hasOwnProperty.call(limits, 'fileSize') ||
      Object.prototype.hasOwnProperty.call(limits, 'parts'))) {
      busboyLimits = {}
      var key
      for (key in limits) {
        busboyLimits[key] = limits[key]
      }

      if (typeof limits.fileSize === 'number' && isFinite(limits.fileSize)) {
        busboyLimits.fileSize = limits.fileSize + 1
      }

      if (typeof limits.parts === 'number' && isFinite(limits.parts)) {
        busboyLimits.parts = limits.parts + 1
      }
    }

    var storage = options.storage
    var fileFilter = options.fileFilter
    var fileStrategy = options.fileStrategy
    var preservePath = options.preservePath
    var defParamCharset = options.defParamCharset
    var defCharset = options.defCharset
    var highWaterMark = options.highWaterMark
    var fileHwm = options.fileHwm
    var streamHandler = options.streamHandler || defaultStreamHandler

    req.body = Object.create(null)

    var busboy
    var appender = null
    var isDone = false
    var readFinished = false
    var errorOccured = false
    var abortCleanupDone = false
    var abortRemovedFiles = new Set()
    var pendingWrites = new Counter()
    var uploadedFiles = []
    var pendingFiles = []

    function done (err) {
      var called = false
      function onFinished () {
        if (called) return
        called = true
        next(err)
      }

      if (isDone) return
      isDone = true
      if (busboy) {
        req.unpipe(busboy)
        setImmediate(() => {
          busboy.removeAllListeners()
        })
      }
      drainStream(req)
      req.resume()

      // - if responding with an error, drain request body before calling
      //     next(err) -- avoids EPIPE on the client (server closing connection
      //     while the client is still sending the request body)
      // - also listen for 'close' so we don't hang when the client aborts (stream may never 'end')
      // - skip waiting if the stream is already destroyed (e.g. client aborted)
      if (err && req.readable && !req.destroyed) {
        req.once('end', onFinished)
        req.once('error', onFinished)
        req.once('close', onFinished)
        return
      }
      next(err)
    }

    function indicateDone () {
      if (readFinished && pendingWrites.isZero() && !errorOccured) done()
    }

    function abortWithError (uploadError, skipPendingWait) {
      if (errorOccured) return
      errorOccured = true

      function finishAbort () {
        // Mark that the abort cleanup has committed its removal list. A file
        // whose engine completes after this point was not in that list, so the
        // completion callback must remove it directly (see _handleFile).
        abortCleanupDone = true

        function remove (file, cb) {
          storage._removeFile(req, file, cb)
        }

        var pendingToRemove = pendingFiles.filter(function (f) { return f.path })
        pendingToRemove.forEach(function (f) { abortRemovedFiles.add(f) })

        var filesToRemove = uploadedFiles.concat(pendingToRemove)
        pendingFiles = []

        removeUploadedFiles(filesToRemove, remove, function (err, storageErrors) {
          if (err) return done(err)

          uploadError.storageErrors = storageErrors
          done(uploadError)
        })
      }

      if (skipPendingWait) {
        finishAbort()
      } else {
        pendingWrites.onceZero(finishAbort)
      }
    }

    function abortWithCode (code, optionalField, optionalFilename) {
      abortWithError(new MulterError(code, optionalField, optionalFilename))
    }

    function handleRequestFailure (err) {
      if (isDone) return
      if (busboy) {
        req.unpipe(busboy)
        busboy.destroy(err)
      }
      abortWithError(err, true)
    }

    req.on('error', function (err) {
      handleRequestFailure(err || new Error('Request error'))
    })

    req.on('aborted', function () {
      handleRequestFailure(new Error('Request aborted'))
    })

    req.on('close', function () {
      if (req.readableEnded) return
      handleRequestFailure(new Error('Request closed'))
    })

    try {
      busboy = Busboy({
        headers: req.headers,
        limits: busboyLimits,
        preservePath: preservePath,
        defParamCharset: defParamCharset,
        defCharset: defCharset,
        highWaterMark: highWaterMark,
        fileHwm: fileHwm
      })
    } catch (err) {
      return next(err)
    }

    appender = new FileAppender(fileStrategy, req)

    // handle text field data
    busboy.on('field', function (fieldname, value, { nameTruncated, valueTruncated }) {
      if (fieldname == null) return abortWithCode('MISSING_FIELD_NAME')

      // fieldNameSize limits the name as it arrived, so keep the raw form for
      // that check before the escapes are reversed.
      var rawFieldname = fieldname
      fieldname = decodeFormDataName(fieldname)

      if (nameTruncated) return abortWithCode('LIMIT_FIELD_KEY')
      if (valueTruncated) return abortWithCode('LIMIT_FIELD_VALUE', fieldname)

      // Work around bug in Busboy (https://github.com/mscdex/busboy/issues/6)
      if (limits && Object.prototype.hasOwnProperty.call(limits, 'fieldNameSize')) {
        if (rawFieldname.length > limits.fieldNameSize) return abortWithCode('LIMIT_FIELD_KEY')
      }

      if (limits && Object.prototype.hasOwnProperty.call(limits, 'fieldNestingDepth')) {
        if (fieldname.split('[').length - 1 > limits.fieldNestingDepth) return abortWithCode('LIMIT_FIELD_NESTING', fieldname)
      }

      if (limits && Object.prototype.hasOwnProperty.call(limits, 'fieldArrayIndexLimit')) {
        if (exceedsArrayIndexLimit(fieldname, limits.fieldArrayIndexLimit)) {
          return abortWithCode('LIMIT_FIELD_ARRAY_INDEX', fieldname)
        }
      }

      try {
        appendField(req.body, fieldname, value)
      } catch {
        return abortWithCode('INVALID_FIELD_NAME', fieldname)
      }
    })

    // handle files
    busboy.on('file', function (fieldname, fileStream, { filename, encoding, mimeType }) {
      var pendingWritesIncremented = false
      var aborting = false
      var accepted = false
      var fileSizeLimitReached = false

      // Reverse the WHATWG escapes once, before anything can build an error
      // about this file, so err.filename and file.originalname are the same
      // string. busboy reports filename as undefined for a part that carries
      // no file, and such a part never reaches an error that names a file.
      var originalname = filename && decodeFormDataName(filename)

      function decrementPendingWrites () {
        if (!pendingWritesIncremented) return
        pendingWritesIncremented = false
        pendingWrites.decrement()
      }

      fileStream.on('error', function (err) {
        decrementPendingWrites()
        abortWithError(err)
      })

      // Register 'limit' synchronously so an async fileFilter can't miss it.
      // Only abort once the file has been accepted.
      fileStream.on('limit', function () {
        fileSizeLimitReached = true
        if (accepted) {
          aborting = true
          abortWithCode('LIMIT_FILE_SIZE', fieldname, originalname)
        }
      })

      if (fieldname == null) return abortWithCode('MISSING_FIELD_NAME')

      // fieldNameSize limits the name as it arrived, so keep the raw form for
      // that check before the escapes are reversed.
      var rawFieldname = fieldname
      fieldname = decodeFormDataName(fieldname)

      // don't attach to the files object, if there is no file
      if (!filename) return fileStream.resume()

      // Work around bug in Busboy (https://github.com/mscdex/busboy/issues/6)
      if (limits && Object.prototype.hasOwnProperty.call(limits, 'fieldNameSize')) {
        if (rawFieldname.length > limits.fieldNameSize) return abortWithCode('LIMIT_FIELD_KEY')
      }

      var file = {
        fieldname: fieldname,
        originalname: originalname,
        encoding: encoding,
        mimetype: mimeType
      }

      var placeholder = appender.insertPlaceholder(file)

      fileFilter(req, file, function (err, includeFile) {
        if (errorOccured) {
          appender.removePlaceholder(placeholder)
          return fileStream.resume()
        }

        if (err) {
          appender.removePlaceholder(placeholder)
          return abortWithError(err)
        }

        if (!includeFile) {
          appender.removePlaceholder(placeholder)
          return fileStream.resume()
        }

        // 'limit' may have fired while an async fileFilter was pending.
        if (fileSizeLimitReached) {
          appender.removePlaceholder(placeholder)
          return abortWithCode('LIMIT_FILE_SIZE', fieldname, originalname)
        }

        accepted = true
        pendingWritesIncremented = true
        pendingWrites.increment()

        Object.defineProperty(file, 'stream', {
          configurable: true,
          enumerable: false,
          value: fileStream
        })

        pendingFiles.push(file)

        storage._handleFile(req, file, function (err, info) {
          var idx = pendingFiles.indexOf(file)
          if (idx !== -1) pendingFiles.splice(idx, 1)

          if (aborting) {
            appender.removePlaceholder(placeholder)
            uploadedFiles.push({ ...file, ...info })
            return decrementPendingWrites()
          }

          if (err) {
            appender.removePlaceholder(placeholder)
            decrementPendingWrites()
            return abortWithError(err)
          }

          var fileInfo = { ...file, ...info }

          // If the abort cleanup already ran while the engine was still
          // naming/writing this file, finishAbort has drained uploadedFiles and
          // will not run again, so pushing here would orphan the file. Remove it
          // directly (this also covers engines slower than the abort: multer-s3,
          // GridFS, async filename). While the abort is still waiting on pending
          // writes, fall through so finishAbort cleans it and keeps storageErrors.
          if (abortCleanupDone) {
            // finishAbort already removed this file if it had a path when the
            // abort ran; removing again could double-clean an engine that does
            // not support it. Just settle the bookkeeping in that case.
            if (abortRemovedFiles.has(file)) {
              appender.removePlaceholder(placeholder)
              decrementPendingWrites()
              return
            }

            return storage._removeFile(req, fileInfo, function () {
              appender.removePlaceholder(placeholder)
              decrementPendingWrites()
            })
          }

          appender.replacePlaceholder(placeholder, fileInfo)
          uploadedFiles.push(fileInfo)
          decrementPendingWrites()
          indicateDone()
        })
      })
    })

    busboy.on('error', function (err) { abortWithError(err) })
    busboy.on('partsLimit', function () { abortWithCode('LIMIT_PART_COUNT') })
    busboy.on('filesLimit', function () { abortWithCode('LIMIT_FILE_COUNT') })
    busboy.on('fieldsLimit', function () { abortWithCode('LIMIT_FIELD_COUNT') })
    busboy.on('close', function () {
      readFinished = true
      indicateDone()
    })

    streamHandler(req, busboy)
  }
}

module.exports = makeMiddleware

var makeMiddleware = require('./lib/make-middleware')

var diskStorage = require('./storage/disk')
var memoryStorage = require('./storage/memory')
var MulterError = require('./lib/multer-error')
var validateLimits = require('./lib/validate-limits')

/**
 * A file parsed from a multipart request.
 *
 * @typedef {Object} File
 * @property {string} fieldname Name of the form field
 * @property {string} originalname Name of the file on the client (client-supplied, treat as untrusted)
 * @property {string} encoding Transfer encoding of the file
 * @property {string} mimetype MIME type of the file
 * @property {number} [size] Size of the file in bytes; set once the file has been stored
 * @property {ReadableStream} [stream] The file data; only present while a storage engine's `_handleFile` runs
 * @property {string} [destination] Folder the file was saved to (`DiskStorage`)
 * @property {string} [filename] Name of the file within `destination` (`DiskStorage`)
 * @property {string} [path] Full path of the saved file (`DiskStorage`)
 * @property {Buffer} [buffer] Contents of the file (`MemoryStorage`)
 */

/**
 * Size limits, passed to busboy. All are optional.
 *
 * @typedef {Object} Limits
 * @property {number} [fieldNameSize=100] Max field name size in bytes
 * @property {number} [fieldSize=1048576] Max field value size in bytes
 * @property {number} [fields=Infinity] Max number of non-file fields
 * @property {number} [fileSize=Infinity] Max file size in bytes (integer or `Infinity`)
 * @property {number} [files=Infinity] Max number of file fields
 * @property {number} [parts=Infinity] Max number of parts (fields + files)
 * @property {number} [headerPairs=2000] Max number of header key/value pairs to parse
 * @property {number} [fieldNestingDepth=Infinity] Max nesting depth of field names (`a[b][c]` has 2 levels)
 * @property {number} [fieldArrayIndexLimit=Infinity] Max numeric array index accepted in field names
 */

/**
 * Decides whether a file is accepted. Call `cb(null, true)` to accept the
 * file, `cb(null, false)` to skip it silently, or `cb(err)` to abort.
 *
 * @callback FileFilter
 * @param {Object} req The request
 * @param {File} file The file being uploaded; `size`, `stream`, `path` and `buffer` are not set yet
 * @param {function(?Error, boolean=): void} cb
 */

/**
 * Storage engine. See StorageEngine.md for the full contract.
 *
 * @typedef {Object} StorageEngine
 * @property {function(Object, File, function(?Error, Object=): void): void} _handleFile
 *   Consumes `file.stream` and calls back with the properties to merge into the file object
 * @property {function(Object, File, function(?Error): void): void} _removeFile
 *   Removes a stored file when the request fails
 */

/**
 * @typedef {Object} Options
