import datetime,hashlib,json,os,pathlib,shutil,subprocess,sys,time
sys.stdout.reconfigure(encoding='utf-8')
R=pathlib.Path(__file__).parent.resolve();OLD=pathlib.Path('$PROBE_ROOT');LINT=pathlib.Path('$LINT_PROBE_ROOT')
NODE=OLD/'tools/node-v24.22.1-win-x64/node.exe';PNPM=OLD/'tools/pnpm/pnpm.exe';WS=R/'workspace'
for d in ['home','cache','temp','logs','evidence','workspace','tools']:(R/d).mkdir(exist_ok=True)
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def environment():
 keep=['SYSTEMROOT','WINDIR','SYSTEMDRIVE','COMSPEC','OS','PROCESSOR_ARCHITECTURE','NUMBER_OF_PROCESSORS','PATHEXT','PROGRAMFILES','PROGRAMFILES(X86)','PROGRAMW6432'];env={k:os.environ[k] for k in keep if k in os.environ}
 home=R/'home';app=home/'AppData/Roaming';local=R/'cache/local'
 for d in [app,local,R/'cache/pnpm',R/'cache/npm',R/'cache/xdg',home/'config',R/'tools/pnpm-home']:d.mkdir(parents=True,exist_ok=True)
 env.update(HOME=str(home),USERPROFILE=str(home),HOMEDRIVE=home.drive,HOMEPATH=str(home)[2:],APPDATA=str(app),LOCALAPPDATA=str(local),TEMP=str(R/'temp'),TMP=str(R/'temp'),PNPM_HOME=str(R/'tools/pnpm-home'),COREPACK_HOME=str(R/'cache/corepack'),XDG_CACHE_HOME=str(R/'cache/xdg'),XDG_CONFIG_HOME=str(home/'config'),XDG_STATE_HOME=str(R/'cache/state'),XDG_DATA_HOME=str(R/'cache/data'),NPM_CONFIG_CACHE=str(R/'cache/npm'),NPM_CONFIG_USERCONFIG=str(home/'.npmrc'),NPM_CONFIG_GLOBALCONFIG=str(home/'global-npmrc'),GIT_CONFIG_GLOBAL=str(home/'.gitconfig'),GIT_CONFIG_NOSYSTEM='1',CI='true',NEXT_TELEMETRY_DISABLED='1',DO_NOT_TRACK='1',NO_COLOR='1',NO_PROXY='localhost,127.0.0.1',NAPI_RS_ENFORCE_VERSION_CHECK='1')
 env['PATH']=os.pathsep.join(map(str,[NODE.parent,PNPM.parent,pathlib.Path('C:/Program Files/Git/cmd'),pathlib.Path('C:/Windows/System32'),pathlib.Path('C:/Windows'),pathlib.Path('C:/Windows/System32/Wbem'),pathlib.Path('C:/Windows/System32/WindowsPowerShell/v1.0')]))
 return env

def footprint():
 size=0;seen=set()
 for root,dirs,files in os.walk(R,followlinks=False):
  dirs[:]=[d for d in dirs if not (pathlib.Path(root)/d).is_symlink() and not (pathlib.Path(root)/d).is_junction()]
  for f in files:
   p=pathlib.Path(root)/f
   try:
    if p.is_symlink():continue
    st=p.stat();identity=(st.st_dev,st.st_ino)
    if identity not in seen:size+=st.st_size;seen.add(identity)
   except FileNotFoundError:pass
 return {'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'unique_file_bytes':size,'free_bytes':shutil.disk_usage(R).free}
def check_budget():
 s=footprint()
 if s['unique_file_bytes']>=3*2**30 or s['free_bytes']<=20*2**30:raise RuntimeError('Storage stop threshold: '+json.dumps(s))
 return s
def verify_tool(tool,expected=None):
 tool=pathlib.Path(tool);assert tool in [NODE,PNPM]
 trusted=json.loads((R/'evidence/tool-identities.json').read_text())['executables'][tool.name]['sha256']
 if sha(tool)!=(expected if expected is not None else trusted):raise RuntimeError('Executable identity mismatch; no subprocess launched')
def kill(p):
 subprocess.run(['C:/Windows/System32/taskkill.exe','/PID',str(p.pid),'/T','/F'],capture_output=True);p.wait(timeout=30)
def run(name,args,cwd=None,timeout=600):
 cwd=pathlib.Path(cwd or WS).resolve();assert cwd.is_relative_to(R);verify_tool(args[0]);samples=[check_budget()]
 target=R/'evidence'/(name+'.json');assert not target.exists(),'Preserve earlier commands/failures'
 rec={'name':name,'args':list(map(str,args)),'cwd':str(cwd),'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 with (R/'logs'/(name+'.log')).open('w',encoding='utf-8') as log:
  p=subprocess.Popen(list(map(str,args)),cwd=cwd,env=environment(),stdout=log,stderr=subprocess.STDOUT);rec['pid']=p.pid;start=time.monotonic()
  try:
   while p.poll() is None:
    if time.monotonic()-start>timeout:raise TimeoutError('Command timeout')
    time.sleep(3);samples.append(check_budget())
   rec['exit_code']=p.returncode
  except BaseException as e:
   kill(p);rec.update(exit_code=p.returncode,error=repr(e))
 rec['ended_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();rec['resource_samples']=samples;target.write_text(json.dumps(rec,indent=2)+'\n',encoding='utf-8')
 print(name,'exit',rec['exit_code']);print((R/'logs'/(name+'.log')).read_text(encoding='utf-8',errors='replace')[-10000:]);return rec
if __name__=='__main__':
 tool={'node':NODE,'pnpm':PNPM}[sys.argv[1]];args=([tool,'--state-dir',R/'cache/pnpm/state'] if tool==PNPM else [tool])+sys.argv[3:];result=run(sys.argv[2],args);sys.exit(0 if result['exit_code']==0 and 'error' not in result else 1)

